import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"آلية فتح موارد الزراعة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/18-修炼资源开放机制.md","filePath":"ar/18-修炼资源开放机制.md","lastUpdated":null}'),d={name:"ar/18-修炼资源开放机制.md"};function e(o,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="آلية-فتح-موارد-الزراعة" tabindex="-1">آلية فتح موارد الزراعة <a class="header-anchor" href="#آلية-فتح-موارد-الزراعة" aria-label="Permalink to &quot;آلية فتح موارد الزراعة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>18</td></tr><tr><td>الوحدة</td><td>القوانين الكونية وأنظمة الزراعة</td></tr><tr><td>الكلمات المفتاحية</td><td>فتح الموارد، موارد الزراعة، آلية التوزيع، مكافحة الاحتكار، عدالة الموارد</td></tr></tbody></table><h2 id="أولاً-خلفية-آلية-فتح-موارد-الزراعة-وأهميتها" tabindex="-1">أولاً: خلفية آلية فتح موارد الزراعة وأهميتها <a class="header-anchor" href="#أولاً-خلفية-آلية-فتح-موارد-الزراعة-وأهميتها" aria-label="Permalink to &quot;أولاً: خلفية آلية فتح موارد الزراعة وأهميتها&quot;">​</a></h2><p>في عصر الافتراس، كانت موارد الزراعة أخطر ما يتنازع عليه. فالأوردة الروحية وحقول الأدوية ومناجم الطاقة والكنوز السماوية والأراضية والمكامن الزراعية السرية كانت محتكرة من قِبل قلة من الأقوياء والطوائف، وكادت جماهير القاع لا تحصل على موارد زراعة نظامية. هذا الاحتكار لم يسبب تصلباً طبقيياً حاداً فحسب، بل أدى أيضاً إلى حروب ومجازر لا حصر لها بسبب التنازع على الموارد. احتكار الموارد هو الأساس الاقتصادي لنظام الافتراس — فما دامت الموارد محتكرة من قلة، «طريق لكل إنسان» لن يكون إلا عبارة فارغة.</p><p>بعد قيام حضارة التكافل المرساة، جُعل «فتح موارد الزراعة» من أهم الإصلاحات المؤسسية. الهدف الأساسي لآلية فتح موارد الزراعة: كسر احتكار الموارد، وضمان حصول كل كائن على موارد الزراعة الأساسية، مع تحفيز الاستخدام الكفء والخلق المستمر للموارد عبر آلية توزيع «من عمل أكثر نال أكثر». فتح الموارد ليس «توزيعاً متساوياً للموارد»، بل «حصولاً عادلاً على الموارد» — على أساس ضمان الحاجات الأساسية، يُربط توزيع الموارد بمساهمة الفرد، مع منع أي شكل من أشكال احتكار الموارد منعاً صارماً.</p><p>تتجلى أهمية آلية فتح موارد الزراعة في أنها: تقتلع تربة الافتراس من أساسها الاقتصادي، وتوفر ضماناً مادياً لتعميم الأنظمة الثلاثمائة حقاً، وتدعم هدف «طريق لكل إنسان» اجتماعياً بالموارد، وتصنع نقطة انطلاق عادلة لتقدم عشرة آلاف عرق المشترك.</p><h2 id="ثانياً-تصنيف-موارد-الزراعة-وتراتيبها" tabindex="-1">ثانياً: تصنيف موارد الزراعة وتراتيبها <a class="header-anchor" href="#ثانياً-تصنيف-موارد-الزراعة-وتراتيبها" aria-label="Permalink to &quot;ثانياً: تصنيف موارد الزراعة وتراتيبها&quot;">​</a></h2><h3 id="_2-1-تصنيف-الموارد" tabindex="-1">2.1 تصنيف الموارد <a class="header-anchor" href="#_2-1-تصنيف-الموارد" aria-label="Permalink to &quot;2.1 تصنيف الموارد&quot;">​</a></h3><p>تنقسم موارد الزراعة في هينغ يوانتشو حسب طبيعتها واستخدامها إلى الفئات الرئيسية التالية:</p><table tabindex="0"><thead><tr><th>فئة الموارد</th><th>المحتوى المحدد</th><th>الاستخدامات الرئيسية</th></tr></thead><tbody><tr><td>موارد الطاقة</td><td>الأوردة الروحية، مناجم الطاقة، بلورات الطاقة الروحية، شظايا طاقة الأصل وغيرها</td><td>توفير مدخلات الطاقة اللازمة للزراعة</td></tr><tr><td>موارد الأدوية</td><td>الأدوية الروحية، الأعشاب الخالدة، مواد الكيمياء، الحبوب الجاهزة وغيرها</td><td>مساعدة الزراعة، وعلاج الجراح والأمراض، وكسر العوائق</td></tr><tr><td>موارد الأدوات</td><td>أسلحة الزراعة، أجهزة القوانين، أجهزة المضاعفة، معدات الفضاء وغيرها</td><td>رفع كفاءة الزراعة، ومساعدة التحكم بالقوانين</td></tr><tr><td>موارد الفضاء</td><td>المكامن الزراعية السرية، مناطق تركيز الطاقة، غرف استيعاب القوانين، فضاء العزل وغيرها</td><td>توفير بيئات زراعية خاصة</td></tr><tr><td>موارد المعرفة</td><td>طرق الزراعة، خبرات الزراعة، مواد بحث القوانين، الوثائق التقنية وغيرها</td><td>تقديم الإرشاد النظري والمنهجي للزراعة</td></tr><tr><td>الموارد الحيوية</td><td>الوحوش الروحية، النباتات الروحية، الكائنات المتعاقدة، الكائنات التكافلية وغيرها</td><td>توفير مساعدة الزراعة، والدورة التكافلية، والقدرات الخاصة</td></tr><tr><td>موارد الأبعاد</td><td>الأبعاد غير المطورة، حقوق استخدام قنوات الأبعاد، شظايا نوى الأبعاد وغيرها</td><td>توفير فضاءات زراعة وتطوير واسعة النطاق</td></tr></tbody></table><h3 id="_2-2-تراتيب-الموارد" tabindex="-1">2.2 تراتيب الموارد <a class="header-anchor" href="#_2-2-تراتيب-الموارد" aria-label="Permalink to &quot;2.2 تراتيب الموارد&quot;">​</a></h3><p>تنقسم جميع موارد الزراعة حسب الندرة والقيمة إلى خمس مراتب:</p><table tabindex="0"><thead><tr><th>المرتبة</th><th>الاسم</th><th>الندرة</th><th>طريقة التوزيع</th></tr></thead><tbody><tr><td>الأولى</td><td>موارد عادية</td><td>واسعة الانتشار، وفيرة الاحتياطي</td><td>فتح مجاني أو توزيع بأسعار منخفضة</td></tr><tr><td>الثانية</td><td>موارد جيدة</td><td>شائعة نسبياً، احتياطي متوسط</td><td>توزيع أساسي + مقابل مساهمة</td></tr><tr><td>الثالثة</td><td>موارد نادرة</td><td>نادرة نسبياً، احتياطي محدود</td><td>مقابل مساهمة + اعتماد بالطلب</td></tr><tr><td>الرابعة</td><td>موارد ملحمية</td><td>نادرة جداً، احتياطي قليل للغاية</td><td>توزيع تنافسي + أولوية لمشاريع مستوى الحضارة</td></tr><tr><td>الخامسة</td><td>موارد أسطورية</td><td>نادرة للغاية، شبه منقرضة</td><td>توزيع خاص من أعلى هيئة قرار في الحضارة</td></tr></tbody></table><h2 id="ثالثاً-المبادئ-الأساسية-لفتح-الموارد" tabindex="-1">ثالثاً: المبادئ الأساسية لفتح الموارد <a class="header-anchor" href="#ثالثاً-المبادئ-الأساسية-لفتح-الموارد" aria-label="Permalink to &quot;ثالثاً: المبادئ الأساسية لفتح الموارد&quot;">​</a></h2><h3 id="_3-1-مبدأ-الضمان-الأساسي" tabindex="-1">3.1 مبدأ الضمان الأساسي <a class="header-anchor" href="#_3-1-مبدأ-الضمان-الأساسي" aria-label="Permalink to &quot;3.1 مبدأ الضمان الأساسي&quot;">​</a></h3><p>يحق لكل كائن الحصول على موارد المرتبتين الأولى والثانية اللازمة للحفاظ على الزراعة الأساسية. تُوزع موارد الضمان الأساسي مجاناً أو بأسعار منخفضة عبر «منظومة ضمان طريق لكل إنسان»، بلا شروط ولا تمييز. يُعدل مجلس جمهورية عشرة آلاف عرق معيار الضمان الأساسي دورياً حسب حالة موارد الحضارة ومرحلة تطورها، ليتوافق مستوى الضمان مع قدرة الحضارة على التحمل.</p><h3 id="_3-2-مبدأ-من-عمل-أكثر-نال-أكثر" tabindex="-1">3.2 مبدأ من عمل أكثر نال أكثر <a class="header-anchor" href="#_3-2-مبدأ-من-عمل-أكثر-نال-أكثر" aria-label="Permalink to &quot;3.2 مبدأ من عمل أكثر نال أكثر&quot;">​</a></h3><p>فوق الضمان الأساسي، يعتمد توزيع موارد المرتبة الثالثة فما فوق أساساً على قيمة مساهمة الفرد في الشبكة التكافلية. كلما كبرت المساهمة، زادت الموارد القابلة للمقايضة وارتفعت مرتبتها. يحفز هذا المبدأ المزارعين على رفع مراتبهم باجتهاد وتقديم مساهمات أكبر للحضارة، مع ضمان تدفق الموارد إلى الأفراد والجماعات الأقدر على استخدامها بأكفأ وجه.</p><h3 id="_3-3-مبدأ-مكافحة-الاحتكار" tabindex="-1">3.3 مبدأ مكافحة الاحتكار <a class="header-anchor" href="#_3-3-مبدأ-مكافحة-الاحتكار" aria-label="Permalink to &quot;3.3 مبدأ مكافحة الاحتكار&quot;">​</a></h3><p>يُمنع منعاً صارماً احتكار موارد الزراعة من أي فرد أو منظمة أو عرق. الإجراءات المحددة لمكافحة الاحتكار:</p><ul><li>ألا تتجاوز موارد المرتبة الثالثة فما فوق التي يملكها فرد أو منظمة واحدة 1% من إجمالي احتياطي الحضارة</li><li>منع الاحتكار والتخزين — لا يجوز لحائزي الموارد تخزينها خبيثةً أو رفع أسعارها في أوقات الندرة</li><li>منع الحيازة الاستئثارية — لا يجوز لجهات خاصة استئثار الموارد العامة (كالأوردة الروحية العامة والمكامن العامة) وحدها</li><li>تُعاقب مخالفات قانون مكافحة الاحتكار بشدة من محكمة المراسي، شاملة مصادرة الموارد، وتصفير قيم المساهمة، وتقييد صلاحيات الزراعة وغيرها</li></ul><h3 id="_3-4-مبدأ-الاستخدام-المستدام" tabindex="-1">3.4 مبدأ الاستخدام المستدام <a class="header-anchor" href="#_3-4-مبدأ-الاستخدام-المستدام" aria-label="Permalink to &quot;3.4 مبدأ الاستخدام المستدام&quot;">​</a></h3><p>يجب أن يتبع تطوير جميع الموارد واستخدامها مبدأ الاستدامة، ويُمنع الاستخراج الافتراسي من نوع «تجفيف البحيرة لاصطياد السمك». المتطلبات المحددة:</p><ul><li>ألا تتجاوز سرعة تطوير الموارد السرعة الطبيعية لتجددها (للموارد غير المتجددة، يجب وضع خطط بديلة)</li><li>يجب أن يخضع تطوير الموارد لتقييم الأثر البيئي، لمنع أضرار لا رجعة فيها للبيئة الإيكولوجية</li><li>للموارد المهددة بالانقراض، تُطبق سياسات منع أو تقييد الاستخراج، حمايةً لقدرتها على التجدد</li><li>التشجيع على استنبات الموارد النادرة وتركيبها صناعياً بالوسائل التقنية (كهندسة القوانين وتقنية المضاعفة)، لتقليل الاعتماد على الموارد الطبيعية</li></ul><h3 id="_3-5-مبدأ-الانفتاح-والشفافية" tabindex="-1">3.5 مبدأ الانفتاح والشفافية <a class="header-anchor" href="#_3-5-مبدأ-الانفتاح-والشفافية" aria-label="Permalink to &quot;3.5 مبدأ الانفتاح والشفافية&quot;">​</a></h3><p>يجب أن تكون عملية توزيع الموارد علنية وشفافة، خاضعة لإشراف جميع الكائنات:</p><ul><li>نشر احتياطيات جميع الموارد العامة وتوزيعها وحالة تطويرها دورياً للمجتمع</li><li>إتاحة معايير توزيع الموارد وعملياته ونتائجه علناً وقابلة للتحقق</li><li>إنشاء آلية اعتراض على التوزيع — يمكن لمن يعترض على نتائج التوزيع طلب إعادة النظر</li><li>إنشاء «لجنة عدالة الموارد» التابعة لمحكمة المراسي، لإشراف خاص على عدالة توزيع الموارد وقانونيته</li></ul><h2 id="رابعاً-الآليات-المحددة-لفتح-الموارد" tabindex="-1">رابعاً: الآليات المحددة لفتح الموارد <a class="header-anchor" href="#رابعاً-الآليات-المحددة-لفتح-الموارد" aria-label="Permalink to &quot;رابعاً: الآليات المحددة لفتح الموارد&quot;">​</a></h2><h3 id="_4-1-آلية-العقود-المرتبطة-بالإنتاج" tabindex="-1">4.1 آلية العقود المرتبطة بالإنتاج <a class="header-anchor" href="#_4-1-آلية-العقود-المرتبطة-بالإنتاج" aria-label="Permalink to &quot;4.1 آلية العقود المرتبطة بالإنتاج&quot;">​</a></h3><p>العقد المرتبط بالإنتاج هو التصميم المؤسسي الأساسي لفتح موارد الزراعة، وقد فُصلت طريقة عمله الأساسية في وثيقة «مبدأ توزيع من عمل أكثر نال أكثر». في مجال فتح الموارد، تطبيقاته المحددة:</p><ul><li><strong>عقود الأوردة الروحية</strong>: تُعقد الأوردة الروحية العامة لمجموعات مزارعين أو مجتمعات أعراق، ويتولى المتعاقد صيانة الوريد وتطويره المستدام، ويحصل على نسبة من إنتاجه</li><li><strong>عقود حقول الأدوية</strong>: تُعقد حقول الأدوية العامة للمزارعين ذوي القدرة على الزراعة، ويتولى المتعاقد زراعة الأدوية الروحية والعناية بها، وتُقسم المحاصيل بنسب</li><li><strong>إدارة المكامن</strong>: تُسند المكامن الزراعية السرية العامة إلى فرق محترفة للإدارة، ويتولى المدير صيانة المكمن وسلامته، ويدفع المستخدمون رسوماً معقولة</li><li><strong>استكشاف الموارد</strong>: تشجيع المزارعين على المشاركة في استكشاف موارد المناطق غير المطورة، ويتمتع المكتشفون بأولوية التعاقد على الموارد الجديدة</li></ul><h3 id="_4-2-آلية-المقايضة-بقيمة-المساهمة" tabindex="-1">4.2 آلية المقايضة بقيمة المساهمة <a class="header-anchor" href="#_4-2-آلية-المقايضة-بقيمة-المساهمة" aria-label="Permalink to &quot;4.2 آلية المقايضة بقيمة المساهمة&quot;">​</a></h3><p>أنشأت الحضارة التكافلية «نظام مقايضة بقيمة المساهمة» موحداً؛ يمكن للمزارعين تجميع قيم مساهمة عبر الإسهام في الشبكة التكافلية، ثم مقايضتها بموارد زراعة متنوعة:</p><ul><li>طرق اكتساب قيم المساهمة تشمل: التقدم الزراعي، ومشاركة المعرفة، والابتكار التقني، والخدمة العامة، والإصلاح البيئي، وحماية الحضارة وغيرها</li><li>يطبق نظام المقايضة «تسعيراً واضحاً» — لكل مورد سعر واضح بقيم المساهمة، يتعدل ديناميكياً حسب ندرة المورد وطلبه</li><li>يدعم النظام وظيفة «السلف» — يمكن للمزارعين الواعدين سلف مبلغ من قيم المساهمة لمقايضة الموارد، يسددونه مستقبلاً عبر المساهمات</li><li>يتصل النظام بشبكة المراسي مباشرة، لضمان سلامة تسجيل قيم المساهمة والمقايضة وموثوقيتها</li></ul><h3 id="_4-3-آلية-الفتح-المجاني-للموارد-العامة" tabindex="-1">4.3 آلية الفتح المجاني للموارد العامة <a class="header-anchor" href="#_4-3-آلية-الفتح-المجاني-للموارد-العامة" aria-label="Permalink to &quot;4.3 آلية الفتح المجاني للموارد العامة&quot;">​</a></h3><p>الأنواع التالية من الموارد مفتوحة مجاناً لجميع الكائنات:</p><ul><li><strong>موارد المعرفة</strong>: الطرائق الأساسية للأنظمة الثلاثمائة، والخبرات الزراعية العامة، ومواد بحث القوانين الأساسية وغيرها</li><li><strong>موارد الطاقة من المرتبة الأولى</strong>: الطاقة الروحية الأساسية، وبلورات الطاقة العادية وغيرها من موارد الطاقة الدنيا واسعة الانتشار</li><li><strong>فضاءات الزراعة العامة</strong>: غرف الزراعة العامة، وغرف استيعاب القوانين الأساسية، وفضاءات العزل العادية وغيرها</li><li><strong>الموارد الطبية الأساسية</strong>: طرائق العلاج الأساسية، والحبوب العادية لالتئام الجراح، وخدمات التأهيل الأساسية وغيرها</li><li><strong>الموارد التعليمية الأساسية</strong>: دورات الزراعة الأساسية، وإرشاد الأساتذة المبتدئين، واستخدام معدات الزراعة العامة وغيرها</li></ul><h3 id="_4-4-آلية-التوزيع-الموجه-للموارد-الخاصة" tabindex="-1">4.4 آلية التوزيع الموجه للموارد الخاصة <a class="header-anchor" href="#_4-4-آلية-التوزيع-الموجه-للموارد-الخاصة" aria-label="Permalink to &quot;4.4 آلية التوزيع الموجه للموارد الخاصة&quot;">​</a></h3><p>للموارد النادرة من المرتبتين الرابعة والخامسة، تُطبق آلية «التوزيع الموجه»:</p><ul><li>تُخصص الموارد النادرة أولاً لمشاريع مستوى الحضارة الكبرى (كبناء المراسي وتطوير الأبعاد والبحث التقني)</li><li>للأفراد ذوي الحاجات الخاصة (كالحاجة لموارد محددة لكسر مراتب أساسية، أو أدوية نادرة لعلاج جراح وأمراض خاصة)، يمكن الحصول على توزيع موجه بالطلب والاعتماد</li><li>تعد «لجنة توزيع الموارد» التابعة لمجلس جمهورية عشرة آلاف عرق خطط توزيع الموارد النادرة، وتُنفذ بعد اعتماد المجلس</li><li>تُعلن نتائج التوزيع الموجه للمجتمع، وتخضع للإشراف</li></ul><h2 id="خامساً-خلق-الموارد-والتنمية-المستدامة" tabindex="-1">خامساً: خلق الموارد والتنمية المستدامة <a class="header-anchor" href="#خامساً-خلق-الموارد-والتنمية-المستدامة" aria-label="Permalink to &quot;خامساً: خلق الموارد والتنمية المستدامة&quot;">​</a></h2><p>فتح موارد الزراعة ليس «توزيع المخزون القائم» فحسب، بل «خلق الزيادة». تشجع الحضارة التكافلية الخلق الصناعي للموارد وتنميتها المستدامة تشجيعاً كبيراً:</p><h3 id="_5-1-الاستنبات-الصناعي-للموارد" tabindex="-1">5.1 الاستنبات الصناعي للموارد <a class="header-anchor" href="#_5-1-الاستنبات-الصناعي-للموارد" aria-label="Permalink to &quot;5.1 الاستنبات الصناعي للموارد&quot;">​</a></h3><ul><li><strong>الزراعة الصناعية للأدوية الروحية</strong>: عبر هندسة القوانين، استنبات الأدوية الروحية في بيئات صناعية، لتقليل الاعتماد على الأدوية البرية</li><li><strong>الإنتاج الصناعي للطاقة</strong>: عبر أجهزة تحويل الطاقة المادية ومولدات رنين القوانين وغيرها من التقنيات، إنتاج الطاقة الروحية وبلورات الطاقة صناعياً</li><li><strong>الاستيلاد الصناعي للوحوش الروحية</strong>: إنشاء قواعد استيلاد الوحوش الروحية، واستيلاد أنواعها صناعياً، حمايةً لتجمعاتها البرية</li><li><strong>البناء الصناعي للمكامن</strong>: عبر تقنيات القانون المكاني، بناء المكامن الزراعية السرية صناعياً، لزيادة معروض فضاءات الزراعة</li></ul><h3 id="_5-2-إعادة-تدوير-الموارد" tabindex="-1">5.2 إعادة تدوير الموارد <a class="header-anchor" href="#_5-2-إعادة-تدوير-الموارد" aria-label="Permalink to &quot;5.2 إعادة تدوير الموارد&quot;">​</a></h3><ul><li><strong>استرجاع الطاقة</strong>: إنشاء أنظمة استرجاع الطاقة، لإعادة تدوير الطاقة المفقودة أثناء الزراعة والمتبددة في القتال وغيرها</li><li><strong>معالجة بقايا الأدوية</strong>: إجراء استخلاص ومعالجة ثانوية لبقايا الكيمياء، لرفع معدل استخدام الموارد الدوائية</li><li><strong>تدوير الأدوات وإعادة تصنيعها</strong>: تدوير أدوات الزراعة التالفة وإعادة تصنيعها، لتقليل هدر المواد</li><li><strong>الاستخدام الدوري للفضاءات</strong>: تنظيف فضاءات العزل المستخدمة وفضاءات الزراعة المؤقتة وإعادة استخدامها دورياً</li></ul><h3 id="_5-3-تقنيات-إحلال-الموارد" tabindex="-1">5.3 تقنيات إحلال الموارد <a class="header-anchor" href="#_5-3-تقنيات-إحلال-الموارد" aria-label="Permalink to &quot;5.3 تقنيات إحلال الموارد&quot;">​</a></h3><ul><li>تشجيع تطوير بدائل الموارد النادرة، وتحقيق «إحلال المواد النادرة بالمواد الشائعة» بالوسائل التقنية</li><li>للموارد الأسطورية غير المتجددة، وضع خطط صارمة للحماية والاستخدام، مع زيادة الاستثمار في أبحاث تقنيات الإحلال</li><li>إنشاء «صندوق أبحاث تقنيات إحلال الموارد» لتمويل المشاريع البحثية ذات الصلة</li></ul><h2 id="سادساً-إشراف-فتح-الموارد-والإنصاف" tabindex="-1">سادساً: إشراف فتح الموارد والإنصاف <a class="header-anchor" href="#سادساً-إشراف-فتح-الموارد-والإنصاف" aria-label="Permalink to &quot;سادساً: إشراف فتح الموارد والإنصاف&quot;">​</a></h2><h3 id="_6-1-آليات-الإشراف" tabindex="-1">6.1 آليات الإشراف <a class="header-anchor" href="#_6-1-آليات-الإشراف" aria-label="Permalink to &quot;6.1 آليات الإشراف&quot;">​</a></h3><ul><li><strong>المراقبة اللحظية لشبكة المراسي</strong>: تراقب الشبكة تطوير جميع الموارد العامة وتوزيعها واستخدامها لحظياً، وتنبه مبكراً عند رصد أي شذوذ</li><li><strong>لجنة عدالة الموارد</strong>: تشرف تحديداً على عدالة توزيع الموارد وقانونيته، وتستقبل البلاغات والشكاوى</li><li><strong>الإشراف الاجتماعي</strong>: تشجيع جميع الكائنات على مراقبة السلوكيات غير السليمة في تطوير الموارد وتوزيعها والتبليغ عنها</li><li><strong>التدقيق الدوري</strong>: تدقيق مستقل سنوي لمؤسسات إدارة الموارد، ونشر النتائج للمجتمع</li></ul><h3 id="_6-2-آليات-الإنصاف" tabindex="-1">6.2 آليات الإنصاف <a class="header-anchor" href="#_6-2-آليات-الإنصاف" aria-label="Permalink to &quot;6.2 آليات الإنصاف&quot;">​</a></h3><ul><li><strong>الاعتراض على التوزيع</strong>: يمكن لمن يعترض على نتائج توزيع الموارد طلب إعادة النظر من لجنة عدالة الموارد</li><li><strong>التحكيم في نزاعات الموارد</strong>: تحكم محكمة المراسي في نزاعات الموارد، ونتائج التحكيم ملزمة قانوناً</li><li><strong>الإنصاف من التعدي</strong>: يمكن للأفراد المتضررين من احتكار الموارد ونهبها وغيرها من السلوكيات رفع دعاوى أمام محكمة المراسي للمطالبة بالتعويض</li><li><strong>الإغاثة الطارئة</strong>: في الحالات الخاصة (كالكوارث والحروب)، يُفعّل نظام توزيع الموارد الطارئ لضمان حاجات المجموعات المتضررة الأساسية من الموارد</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>آلية فتح موارد الزراعة هي جوهر النظام الاقتصادي لحضارة التكافل المرساة. فبمبادئها الخمسة «الضمان الأساسي + من عمل أكثر نال أكثر + مكافحة الاحتكار + الاستدامة + الانفتاح والشفافية»، تبني نظام توزيع موارد عادلاً وكفؤاً ومستداماً. الهدف الأسمى للآلية ليس حصول جميع الكائنات على كمية متساوية من الموارد، بل حصول كل كائن على فرصة عادلة للحصول عليها، وتدفق الموارد إلى حيث تخلق أكبر قيمة، ونمو موارد الحضارة الكلية باستمرار في ظل شروط مستدامة. عندما تتوقف موارد الزراعة عن كونها ملكاً خاصاً يحتكره قلة، وتصبح ثروة عامة تتقاسمها عشرة آلاف عرق وتتضاعف بالدورة، حينها فقط يرسخ «طريق لكل إنسان» جذوره، ويتحقق هدف تقدم عشرة آلاف عرق المشترك حقاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (مبدأ توزيع من عمل أكثر نال أكثر)</li><li>08-人人有路保障体系 (منظومة ضمان طريق لكل إنسان)</li><li>22-资源分配联产承包机制 (آلية العقود المرتبطة بالإنتاج لتوزيع الموارد)</li></ul>',57)])])}const _=a(d,[["render",e]]);export{c as __pageData,_ as default};
